using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.AppHost.Tests;

public class AppHostTests
{
    [Fact]
    public async Task AppHost_StartsSuccessfully()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await builder.BuildAsync();
        await app.StartAsync();

        await app.WaitForResourcesToStartAsync();
    }

    [Fact]
    public async Task AppHost_ResourcesReachRunningState()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await builder.BuildAsync();
        await app.StartAsync();

        var resourceNotificationService = app.Services
            .GetRequiredService<ResourceNotificationService>();

        // Verify the app model was built without errors
        var appModel = app.Services.GetRequiredService<DistributedApplicationModel>();
        Assert.NotNull(appModel);
    }
}
